<div class="page-head"><div><h1>Publicar nova vaga</h1><p>Informe tudo que o profissional precisa saber antes de aceitar.</p></div></div>
<form method="post" class="form-layout"><?=csrf_field()?>
<section class="panel form-panel"><h2>1. Função e quantidade</h2><div class="form-grid"><div><label>Categoria *</label><select name="category_id" required><option value="">Selecione</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Título da vaga *</label><input name="title" placeholder="Ex.: Garçom - Evento corporativo" required></div><div><label>Quantidade de profissionais *</label><input type="number" min="1" max="100" name="required_workers" value="1" required></div><div><label>Valor por profissional *</label><div class="money-input"><span>R$</span><input type="number" step="0.01" min="0" name="value" value="160.00" required></div></div><div class="full"><label>Descrição</label><textarea name="description" rows="3" placeholder="Descreva a atividade e o contexto do turno"></textarea></div></div></section>
<section class="panel form-panel"><h2>2. Data e horário</h2><div class="form-grid three"><div><label>Data *</label><input type="date" name="date" value="<?=date('Y-m-d',strtotime('+1 day'))?>" required></div><div><label>Entrada *</label><input type="time" name="start_time" value="18:00" required></div><div><label>Saída *</label><input type="time" name="end_time" value="02:00" required></div></div></section>
<section class="panel form-panel"><h2>3. Local e orientações</h2><div class="form-grid"><div class="full"><label>Endereço *</label><input name="address" value="Av. das Nações Unidas, 12551" required></div><div><label>Cidade *</label><input name="city" value="São Paulo" required></div><div><label>UF *</label><input name="state" value="SP" maxlength="2" required></div><div class="full"><label>Uniforme / Dress code</label><textarea name="dress_code" rows="2">Calça preta, camisa branca e sapato social preto.</textarea></div><div class="full"><label>Observações</label><textarea name="notes" rows="3" placeholder="Instruções de acesso, refeição, responsável no local..."></textarea></div></div></section>
<div class="form-actions"><a class="btn btn-soft" href="<?=e(url('empresa/vagas'))?>">Cancelar</a><button class="btn btn-primary" type="submit">Publicar vaga</button></div></form>
